#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD_A=998244353, MOD_B=1000000007;

long long count=0, n_input, low_sum_value, result=0, pwr[8];
vector<int> array[7];

void generate(int level, int val)
{
    int tmp=(count+MOD_A-val)%MOD_A;
    array[level].push_back(tmp);
    low_sum_value=(low_sum_value+tmp)%MOD_B;
    count++;
    if(level<6)
    {
        for(int d=0;d<10;d++) generate(level+1, val*10+d);
    }
}

void process(int depth, long long x)
{
    if(x>n_input) return;
    int i;
    if(x*pwr[6]+pwr[6]-1<=n_input && x*pwr[7]>n_input)
    {
        for(i=0;i<=6;i++)
        {
            long long delta=(count+(MOD_A-pwr[i])*x)%MOD_A;
            result=(result+(delta+MOD_B-MOD_A)*pwr[i]+MOD_A*(lower_bound(array[i].begin(),array[i].end(),MOD_A-delta)-array[i].begin()))%MOD_B;
        }
        result=(result+low_sum_value)%MOD_B;
        count+=1111111;
        return;
    }
    result=(result+(count+MOD_A-x%MOD_A)%MOD_A)%MOD_B;
    count++;
    for(i=depth?0:1;i<10;i++) process(depth+1,x*10+i);
}

int main()
{
    int i;
    pwr[0]=1;
    for(i=1;i<=7;i++) pwr[i]=pwr[i-1]*10;
    generate(0,0);
    for(i=1;i<=6;i++) sort(array[i].begin(),array[i].end());
    cin>>n_input;
    count=0;
    process(0,0);
    cout<<result<<endl;
    return 0;
}
